import{_ as s,o,c as a,a3 as d}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Tenant API v1 — Purchase Orders","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Purchase Orders | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-purchase-orders"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Purchase Orders | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-purchase-orders"}]]},"headers":[],"relativePath":"api/tenant-v1-purchase-orders.md","filePath":"api/tenant-v1-purchase-orders.md","lastUpdated":1785934302000}'),r={name:"api/tenant-v1-purchase-orders.md"};function t(i,e,c,n,h,p){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="tenant-api-v1-—-purchase-orders" tabindex="-1">Tenant API v1 — Purchase Orders <a class="header-anchor" href="#tenant-api-v1-—-purchase-orders" aria-label="Permalink to &quot;Tenant API v1 — Purchase Orders&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>module:purchase-orders</code>, plus permission middleware / policies.</p><p>Requires the <strong>Vendors</strong> module (hard <code>module_dependencies</code> row) — Marketplace blocks installing Purchase Orders on a workspace that doesn&#39;t already have Vendors, since every purchase order requires a vendor.</p><p>Assignee scoping: without <code>purchase-orders.assign</code> (and not superadmin), list/stats/view/update/<strong>send</strong>/<strong>receive</strong>/<strong>cancel</strong> only include purchase orders where <code>assigned_to</code> is the current user.</p><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><h3 id="get-purchase-orders-stats" tabindex="-1">GET <code>/purchase-orders/stats</code> <a class="header-anchor" href="#get-purchase-orders-stats" aria-label="Permalink to &quot;GET `/purchase-orders/stats`&quot;">​</a></h3><p>Same filters as list (minus pagination/sort). Response:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;total_purchase_orders&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;my_purchase_orders&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;draft&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;sent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;partially_received&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;received&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;cancelled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;scope&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;org | mine&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="purchase-orders-crud" tabindex="-1">Purchase Orders CRUD <a class="header-anchor" href="#purchase-orders-crud" aria-label="Permalink to &quot;Purchase Orders CRUD&quot;">​</a></h2><h3 id="get-purchase-orders" tabindex="-1">GET <code>/purchase-orders</code> <a class="header-anchor" href="#get-purchase-orders" aria-label="Permalink to &quot;GET `/purchase-orders`&quot;">​</a></h3><p>Query: <code>search</code> (matches <code>title</code> or <code>number</code>), <code>status</code> (<code>draft</code>|<code>sent</code>|<code>partially_received</code>|<code>received</code>|<code>cancelled</code>), <code>vendor_id</code>, <code>assigned_to</code> (<code>unassigned</code> or user id), <code>my_purchase_orders</code>, <code>trashed</code> (<code>true</code>|<code>only</code>), <code>sort</code>, <code>direction</code>, <code>page</code>, <code>per_page</code>.</p><p>List items include <code>status</code>, <code>currency</code>, <code>subtotal</code>/<code>tax_total</code>/<code>total</code>, <code>order_date</code>, <code>expected_date</code>, <code>vendor</code> ref, assignee/creator refs, and <code>latest_note</code>.</p><h3 id="post-purchase-orders" tabindex="-1">POST <code>/purchase-orders</code> <a class="header-anchor" href="#post-purchase-orders" aria-label="Permalink to &quot;POST `/purchase-orders`&quot;">​</a></h3><p>Body: <code>vendor_id</code> (required, must belong to the tenant and the Vendors module must be entitled), <code>title</code> (required), <code>notes</code>, <code>currency</code> (3-letter, default <code>USD</code>), <code>order_date</code>, <code>expected_date</code> (dates), <code>assigned_to</code>, <code>lines</code> (array of <code>{ description, quantity, unit_price, tax_rate, sort_order, product_id? }</code>). <code>product_id</code> is optional and must reference an entitled, tenant-scoped Product when supplied.</p><p><code>subtotal</code>, <code>tax_total</code>, and <code>total</code> are computed server-side from <code>lines</code> — do not send them. Status always starts at <code>draft</code>; <code>number</code> is auto-generated (<code>PO-00001</code>, configurable via the <code>purchase_orders_number_prefix</code> tenant setting).</p><h3 id="get-purchase-orders-id" tabindex="-1">GET <code>/purchase-orders/{id}</code> <a class="header-anchor" href="#get-purchase-orders-id" aria-label="Permalink to &quot;GET `/purchase-orders/{id}`&quot;">​</a></h3><p>Includes vendor, assignee, creator, lines, notes, and timeline activities.</p><h3 id="put-purchase-orders-id" tabindex="-1">PUT <code>/purchase-orders/{id}</code> <a class="header-anchor" href="#put-purchase-orders-id" aria-label="Permalink to &quot;PUT `/purchase-orders/{id}`&quot;">​</a></h3><p>Partial update of <strong>draft</strong> purchase orders only — including replacing the full <code>lines</code> set (recalculates totals). Non-draft purchase orders return 422 on <code>status</code> (<code>Only draft purchase orders can be edited.</code>). Assignment after send uses <code>POST /purchase-orders/{id}/assign</code>.</p><h3 id="delete-purchase-orders-id" tabindex="-1">DELETE <code>/purchase-orders/{id}</code> <a class="header-anchor" href="#delete-purchase-orders-id" aria-label="Permalink to &quot;DELETE `/purchase-orders/{id}`&quot;">​</a></h3><p>Soft delete. Permission: <code>purchase-orders.delete</code>.</p><h3 id="post-purchase-orders-id-restore" tabindex="-1">POST <code>/purchase-orders/{id}/restore</code> <a class="header-anchor" href="#post-purchase-orders-id-restore" aria-label="Permalink to &quot;POST `/purchase-orders/{id}/restore`&quot;">​</a></h3><p>Permission: <code>purchase-orders.restore</code>.</p><h3 id="delete-purchase-orders-id-force" tabindex="-1">DELETE <code>/purchase-orders/{id}/force</code> <a class="header-anchor" href="#delete-purchase-orders-id-force" aria-label="Permalink to &quot;DELETE `/purchase-orders/{id}/force`&quot;">​</a></h3><p>Permanently delete a soft-deleted purchase order. Permission: <code>purchase-orders.force.delete</code> (owner/superadmin only by default).</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><h3 id="post-purchase-orders-id-assign" tabindex="-1">POST <code>/purchase-orders/{id}/assign</code> <a class="header-anchor" href="#post-purchase-orders-id-assign" aria-label="Permalink to &quot;POST `/purchase-orders/{id}/assign`&quot;">​</a></h3><p><code>{ &quot;assigned_to&quot;: number|null }</code></p><p>Permission: <code>purchase-orders.assign</code>.</p><h3 id="post-purchase-orders-id-send" tabindex="-1">POST <code>/purchase-orders/{id}/send</code> <a class="header-anchor" href="#post-purchase-orders-id-send" aria-label="Permalink to &quot;POST `/purchase-orders/{id}/send`&quot;">​</a></h3><p>Transitions <code>draft → sent</code>. Backfills <code>order_date</code> to today if unset. Permission: <code>purchase-orders.send</code> (assignee-scoped unless the actor has <code>purchase-orders.assign</code> or is superadmin). <strong>Status-only</strong> — does not email or generate a PDF.</p><h3 id="post-purchase-orders-id-receive" tabindex="-1">POST <code>/purchase-orders/{id}/receive</code> <a class="header-anchor" href="#post-purchase-orders-id-receive" aria-label="Permalink to &quot;POST `/purchase-orders/{id}/receive`&quot;">​</a></h3><p><code>{ &quot;status&quot;: &quot;partially_received&quot;|&quot;received&quot;, &quot;warehouse_id&quot;: 2 }</code></p><p>Transitions <code>sent → partially_received|received</code> or <code>partially_received → received</code>. Any other <code>status</code> value is rejected with a 422 before the state machine is even evaluated. <code>warehouse_id</code> is optional for receipt posting. Permission: <code>purchase-orders.receive</code> (assignee-scoped unless the actor has <code>purchase-orders.assign</code> or is superadmin). <code>partially_received</code> is acknowledgement-only. When Products and Inventory are entitled, <code>received</code> posts stock-in once for each linked <code>track_stock</code> product line, to <code>warehouse_id</code> or the default warehouse.</p><h3 id="post-purchase-orders-id-cancel" tabindex="-1">POST <code>/purchase-orders/{id}/cancel</code> <a class="header-anchor" href="#post-purchase-orders-id-cancel" aria-label="Permalink to &quot;POST `/purchase-orders/{id}/cancel`&quot;">​</a></h3><p>Transitions <code>draft|sent|partially_received → cancelled</code>. Permission: <code>purchase-orders.cancel</code> (assignee-scoped unless the actor has <code>purchase-orders.assign</code> or is superadmin).</p><h3 id="post-purchase-orders-id-status" tabindex="-1">POST <code>/purchase-orders/{id}/status</code> <a class="header-anchor" href="#post-purchase-orders-id-status" aria-label="Permalink to &quot;POST `/purchase-orders/{id}/status`&quot;">​</a></h3><p><code>{ &quot;status&quot;: &quot;draft&quot;|&quot;sent&quot;|&quot;partially_received&quot;|&quot;received&quot;|&quot;cancelled&quot; }</code></p><p>Authorization depends on the target status:</p><ul><li><code>sent</code> → <code>purchase-orders.send</code></li><li><code>partially_received</code> / <code>received</code> → <code>purchase-orders.receive</code> (same service path as <code>/receive</code>, including inventory posting when entitled; no <code>warehouse_id</code> on this body — uses the default warehouse)</li><li><code>cancelled</code> → <code>purchase-orders.cancel</code></li><li>other → <code>purchase-orders.update</code></li></ul><p>Rejects disallowed transitions with a 422 validation error on <code>status</code>. Records a <code>status_changed</code> timeline entry.</p><h3 id="post-purchase-orders-id-notes" tabindex="-1">POST <code>/purchase-orders/{id}/notes</code> <a class="header-anchor" href="#post-purchase-orders-id-notes" aria-label="Permalink to &quot;POST `/purchase-orders/{id}/notes`&quot;">​</a></h3><p><code>{ &quot;body&quot;: string }</code></p><p>Permission: <code>purchase-orders.update</code>.</p><h3 id="get-purchase-orders-id-timeline" tabindex="-1">GET <code>/purchase-orders/{id}/timeline</code> <a class="header-anchor" href="#get-purchase-orders-id-timeline" aria-label="Permalink to &quot;GET `/purchase-orders/{id}/timeline`&quot;">​</a></h3><p>Domain timeline entries (<code>created</code>, <code>updated</code>, <code>assigned</code>, <code>status_changed</code>, <code>note_added</code>, <code>deleted</code>, <code>restored</code>, <code>converted</code>).</p><h2 id="convert-to-expense-soft-dependency-on-expenses" tabindex="-1">Convert to expense (soft dependency on Expenses) <a class="header-anchor" href="#convert-to-expense-soft-dependency-on-expenses" aria-label="Permalink to &quot;Convert to expense (soft dependency on Expenses)&quot;">​</a></h2><h3 id="post-purchase-orders-id-convert" tabindex="-1">POST <code>/purchase-orders/{id}/convert</code> <a class="header-anchor" href="#post-purchase-orders-id-convert" aria-label="Permalink to &quot;POST `/purchase-orders/{id}/convert`&quot;">​</a></h3><p>Permission: <code>purchase-orders.convert</code>.</p><p>Creates a <strong>draft</strong> <code>Expense</code> from the purchase order and returns it (201). Requires the <strong>Expenses</strong> module to be entitled on the workspace — this is a soft, call-time check (no <code>module_dependencies</code> row), so Purchase Orders keeps working with Expenses uninstalled and this single endpoint returns a 422 until Expenses is installed:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;The Expenses module is not available for this workspace.&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;errors&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;purchase_order&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;The Expenses module is not available for this workspace.&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Other failure cases (also 422):</p><ul><li>The purchase order&#39;s <code>status</code> is not <code>sent</code>, <code>partially_received</code>, or <code>received</code> (<code>draft</code> and <code>cancelled</code> are not convertible).</li><li>The purchase order has already been converted (one-time — checked by an existing <code>Expense</code> row with this <code>purchase_order_id</code>, including soft-deleted ones).</li></ul><p>Field mapping onto the new expense: <code>title</code> ← PO <code>title</code>, <code>amount</code> ← PO <code>total</code>, <code>tax_amount</code> ← PO <code>tax_total</code>, <code>currency</code>/<code>vendor_id</code>/<code>assigned_to</code>/<code>notes</code> ← copied from the PO, <code>category</code> is always <code>other</code>, <code>expense_date</code> defaults to today. The conversion is recorded as a <code>converted</code> timeline entry on the purchase order and the created expense&#39;s id is exposed on the purchase order resource as <code>converted_expense_id</code> once loaded.</p>',55)])])}const k=s(r,[["render",t]]);export{u as __pageData,k as default};
